export const dynamic = 'force-dynamic';

export default function Home() {
  const timestamp = new Date().toISOString();

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>Current server timestamp (changes on each page load):</p>
      <div style={{ 
        padding: '1rem', 
        backgroundColor: '#f0f0f0', 
        borderRadius: '0.5rem',
        margin: '1rem 0',
        fontFamily: 'monospace'
      }}>
        {timestamp}
      </div>
      <p>This timestamp is generated on the server for each request and is not prerendered at build time.</p>
    </main>
  );
}

